/**
 * Flags emoji pages whose content is near-identical to another page.
 *
 * Why this exists
 * ---------------
 * A large batch of the emoji catalog was generated by swapping a handful of
 * words into a fixed sentence template. The pages looked plausible on their
 * own but collapsed into each other: the five skin-tone variants of an emoji
 * were the same paragraph with the tone word changed, and several slugs
 * describing the same glyph carried byte-identical copy. Two visitors who
 * opened neighbouring pages saw the same words, and search engines saw the
 * same page twice.
 *
 * What this does
 * --------------
 * It builds a tf-idf vector per published emoji page and reports two things:
 *
 *   1. Hard duplicates — any two pages whose cosine similarity is at or above
 *      0.95. These are pages that are saying the same thing.
 *   2. Family spread — for every skin-tone family, how similar the five
 *      variants of one emoji are to each other. Two pages that differ only by
 *      a swatch should still read as two pages.
 *
 * A single global similarity threshold is not enough on its own. Every page
 * about, say, a light skin tone shares the vocabulary of that tone, so a
 * corpus-wide sweep at a moderate threshold reports thousands of pairs that
 * are supposed to sound alike. The two checks above are the ones that point
 * at real duplication.
 *
 * Usage:
 *   bun run check:similarity                 # report duplicates and family spread
 *   bun run check:similarity -- --threshold 0.98
 *   bun run check:similarity -- --strict     # exit 1 when the backlog grows
 *   bun run check:similarity -- --top 40
 */

import fs from 'fs';
import path from 'path';

const EMOJI_DIR = path.join(process.cwd(), 'src', 'data', 'emojis');

/** Similarity at or above which two pages are reported as near-duplicates. */
const DEFAULT_THRESHOLD = 0.95;
/** How many offending pairs to print. */
const DEFAULT_TOP = 25;
/**
 * The similarity two variants of the same emoji may not exceed.
 *
 * The five skin-tone pages of one emoji cover the same gesture, so some
 * overlap is expected — they share the family profile and the wording of the
 * tone. What they must not do is read as the same page five times.
 */
const FAMILY_SIMILARITY_LIMIT = 0.9;
/**
 * The similarity at which two pages count as genuine duplicates.
 *
 * The reporting threshold is deliberately lower — it is there to find the
 * next batch worth rewriting. This one is the line where two pages are
 * saying the same thing, and it is what the CI gate is built on.
 */
const DUPLICATE_THRESHOLD = 0.95;
/**
 * The number of duplicate page pairs the catalog is allowed to carry.
 *
 * The skin-tone rewrite cleared every duplicate inside the Fitzpatrick
 * families, but the catalog still holds a backlog of alias slugs that share
 * a glyph and a copy — the blood types, the clock faces, the arrows, the
 * colour circles and a couple of dozen more. Those need a canonical-slug
 * decision and redirects rather than a rewrite, so the checker is used as a
 * ratchet: it fails when the count grows, and the number is lowered by hand
 * as the backlog is cleared.
 */
const BASELINE_OFFENDER_COUNT = 28;
/**
 * Terms appearing in more than this many pages are ignored when generating
 * candidate pairs. They cannot narrow anything down and the posting lists
 * get long enough to slow the scan down.
 */
const MAX_DOCUMENT_FREQUENCY = 300;

const STOP_WORDS = new Set(
  (
    'the a an is are was were be been being of to in on for with and or but if then than that this it its ' +
    'as at by from not no so very more most other one two they them their you your we our i me my he she ' +
    'his her what does mean how when why'
  ).split(' ')
);

interface Page {
  slug: string;
  /** Relative file path, for output. */
  file: string;
  /** The skin-tone family this page belongs to, if any. */
  family: string | undefined;
  text: string;
}

interface Offender {
  a: string;
  b: string;
  similarity: number;
}

/** Split a string into lowercase content words. */
function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9 ]+/g, ' ')
    .split(/\s+/)
    .filter((word) => word.length > 2 && !STOP_WORDS.has(word));
}

/**
 * Flatten every text field of an emoji page into one comparable blob.
 * Fields that carry no editorial content (slugs, unicode codepoints, category
 * names) are deliberately left out.
 */
function pageText(emoji: Record<string, unknown>): string {
  const longForm = (emoji.longForm ?? {}) as Record<string, unknown>;
  const faqs = (longForm.faqs ?? []) as Array<Record<string, string>>;
  const examples = (emoji.conversationExamples ?? []) as Array<Record<string, string>>;
  const contextMeanings = (emoji.contextMeanings ?? []) as Array<Record<string, string>>;
  const platformNotes = (emoji.platformNotes ?? []) as Array<Record<string, string>>;
  const generationalNotes = (emoji.generationalNotes ?? []) as Array<Record<string, string>>;

  return [
    emoji.tldr,
    emoji.baseMeaning,
    longForm.overview,
    longForm.howPeopleUseIt,
    longForm.whenNotToUse,
    longForm.howToReply,
    ...faqs.map((f) => `${f.question} ${f.answer}`),
    ...examples.map((e) => `${e.message} ${e.interpretation}`),
    ...contextMeanings.map((c) => `${c.meaning} ${c.example}`),
    ...platformNotes.map((p) => p.note),
    ...generationalNotes.map((g) => g.note),
  ]
    .filter((value): value is string => typeof value === 'string' && value.length > 0)
    .join(' ');
}

/** Load every published emoji page. `*-emoji.json` files are not published. */
function loadPages(): Page[] {
  return fs
    .readdirSync(EMOJI_DIR)
    .filter((name) => name.endsWith('.json') && !name.endsWith('-emoji.json'))
    .sort()
    .map((name) => {
      const emoji = JSON.parse(fs.readFileSync(path.join(EMOJI_DIR, name), 'utf-8')) as Record<
        string,
        unknown
      >;
      return {
        slug: (emoji.slug as string) ?? name.slice(0, -5),
        file: path.join('src', 'data', 'emojis', name),
        family: emoji.skinToneBase as string | undefined,
        text: pageText(emoji),
      };
    });
}

/** tf-idf vectors, L2-normalized so the dot product is a cosine similarity. */
function buildVectors(pages: Page[]): Map<string, number>[] {
  const tokens = pages.map((page) => tokenize(page.text));

  const documentFrequency = new Map<string, number>();
  for (const pageTokens of tokens) {
    for (const term of new Set(pageTokens)) {
      documentFrequency.set(term, (documentFrequency.get(term) ?? 0) + 1);
    }
  }

  const idf = (term: string): number =>
    Math.log(pages.length / (1 + (documentFrequency.get(term) ?? 0))) + 1;

  return tokens.map((pageTokens) => {
    const raw = new Map<string, number>();
    for (const term of pageTokens) {
      raw.set(term, (raw.get(term) ?? 0) + 1);
    }
    const weighted = new Map<string, number>();
    for (const [term, count] of raw) {
      weighted.set(term, count * idf(term));
    }
    let squaredNorm = 0;
    for (const weight of weighted.values()) squaredNorm += weight * weight;
    const norm = Math.sqrt(squaredNorm) || 1;
    for (const [term, weight] of weighted) weighted.set(term, weight / norm);
    return weighted;
  });
}

/** Cosine similarity of two normalized sparse vectors. */
function cosine(a: Map<string, number>, b: Map<string, number>): number {
  const [small, large] = a.size <= b.size ? [a, b] : [b, a];
  let dot = 0;
  for (const [term, weight] of small) {
    const other = large.get(term);
    if (other !== undefined) dot += weight * other;
  }
  return dot;
}

/**
 * Find page pairs worth comparing. Two pages can only be similar if they
 * share a term, so an inverted index over the corpus gives the candidates
 * without an O(n^2) sweep.
 */
function candidatePairs(pages: Page[], vectors: Map<string, number>[]): Array<[number, number]> {
  const postings = new Map<string, number[]>();
  pages.forEach((page, index) => {
    for (const term of vectors[index].keys()) {
      const list = postings.get(term);
      if (list) list.push(index);
      else postings.set(term, [index]);
    }
  });

  const seen = new Set<string>();
  const pairs: Array<[number, number]> = [];
  for (const [term, indexes] of postings) {
    if (indexes.length < 2 || indexes.length > MAX_DOCUMENT_FREQUENCY) continue;
    for (let i = 0; i < indexes.length; i += 1) {
      for (let j = i + 1; j < indexes.length; j += 1) {
        const key =
          indexes[i] < indexes[j] ? `${indexes[i]}:${indexes[j]}` : `${indexes[j]}:${indexes[i]}`;
        if (seen.has(key)) continue;
        seen.add(key);
        pairs.push([indexes[i], indexes[j]]);
      }
    }
  }
  return pairs;
}

function parseArgs(argv: string[]): {
  threshold: number;
  top: number;
  strict: boolean;
  familyLimit: number;
} {
  let threshold = DEFAULT_THRESHOLD;
  let top = DEFAULT_TOP;
  let strict = false;
  let familyLimit = FAMILY_SIMILARITY_LIMIT;

  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--threshold' && argv[i + 1]) {
      threshold = Number(argv[i + 1]);
      i += 1;
    } else if (arg.startsWith('--threshold=')) {
      threshold = Number(arg.split('=')[1]);
    } else if (arg === '--top' && argv[i + 1]) {
      top = Number(argv[i + 1]);
      i += 1;
    } else if (arg.startsWith('--top=')) {
      top = Number(arg.split('=')[1]);
    } else if (arg === '--family-limit' && argv[i + 1]) {
      familyLimit = Number(argv[i + 1]);
      i += 1;
    } else if (arg.startsWith('--family-limit=')) {
      familyLimit = Number(arg.split('=')[1]);
    } else if (arg === '--strict') {
      strict = true;
    }
  }

  return { threshold, top, strict, familyLimit };
}

function main(): void {
  const { threshold, top, strict, familyLimit } = parseArgs(process.argv.slice(2));

  const pages = loadPages();
  const vectors = buildVectors(pages);

  const offenders: Offender[] = [];
  let duplicateCount = 0;
  for (const [i, j] of candidatePairs(pages, vectors)) {
    const similarity = cosine(vectors[i], vectors[j]);
    if (similarity >= DUPLICATE_THRESHOLD) duplicateCount += 1;
    if (similarity >= threshold) {
      offenders.push({ a: pages[i].slug, b: pages[j].slug, similarity });
    }
  }

  offenders.sort((x, y) => y.similarity - x.similarity);

  console.log(`Checked ${pages.length} published emoji pages.`);
  console.log(
    `Found ${offenders.length} pair(s) at or above ${threshold.toFixed(2)} cosine similarity.`
  );

  if (offenders.length > 0) {
    console.log('');
    for (const offender of offenders.slice(0, top)) {
      console.log(`  ${offender.similarity.toFixed(3)}  ${offender.a}  ||  ${offender.b}`);
    }
    if (offenders.length > top) {
      console.log(`  ... and ${offenders.length - top} more`);
    }
  }

  // --- Skin-tone family spread -------------------------------------------------
  const families = new Map<string, number[]>();
  pages.forEach((page, index) => {
    const base = page.family;
    if (!base) return;
    const group = families.get(base) ?? [];
    group.push(index);
    families.set(base, group);
  });

  const spread: Array<{ family: string; max: number; mean: number }> = [];
  for (const [family, indexes] of families) {
    let max = 0;
    let total = 0;
    let pairs = 0;
    for (let i = 0; i < indexes.length; i += 1) {
      for (let j = i + 1; j < indexes.length; j += 1) {
        const similarity = cosine(vectors[indexes[i]], vectors[indexes[j]]);
        total += similarity;
        pairs += 1;
        if (similarity > max) max = similarity;
      }
    }
    spread.push({ family, max, mean: pairs > 0 ? total / pairs : 0 });
  }
  spread.sort((x, y) => y.max - x.max);

  const meanSpread =
    spread.length > 0 ? spread.reduce((sum, entry) => sum + entry.mean, 0) / spread.length : 0;
  const worstFamily = spread[0];

  console.log('');
  console.log(
    `Skin-tone families: ${families.size}, mean intra-family similarity ` +
      `${meanSpread.toFixed(3)}, worst ${worstFamily ? worstFamily.family : 'n/a'} ` +
      `at ${worstFamily ? worstFamily.max.toFixed(3) : '0.000'}.`
  );

  const overLimit = spread.filter((entry) => entry.max > familyLimit);
  if (overLimit.length > 0) {
    console.log('');
    for (const entry of overLimit.slice(0, top)) {
      console.log(`  ${entry.max.toFixed(3)}  ${entry.family}`);
    }
  }

  if (!strict) return;

  let failed = false;

  const delta = duplicateCount - BASELINE_OFFENDER_COUNT;
  if (delta > 0) {
    failed = true;
    console.error('');
    console.error(
      `Near-duplicate emoji pages found: ${duplicateCount} pairs at or above ` +
        `${DUPLICATE_THRESHOLD.toFixed(2)}, ${delta} more than the recorded baseline of ` +
        `${BASELINE_OFFENDER_COUNT}. Rewrite the copy, or lower the threshold.`
    );
  } else if (delta < 0) {
    console.log('');
    console.log(
      `${-delta} duplicate pair(s) below the recorded baseline of ${BASELINE_OFFENDER_COUNT}. Lower ` +
        `BASELINE_OFFENDER_COUNT in scripts/check-content-similarity.ts to keep the ratchet tight.`
    );
  }

  if (overLimit.length > 0) {
    failed = true;
    console.error('');
    console.error(
      `${overLimit.length} skin-tone family/families above the ${familyLimit.toFixed(2)} limit: ` +
        `${overLimit.map((entry) => entry.family).join(', ')}. Rewrite the copy so the variants of ` +
        `one emoji read as five pages.`
    );
  }

  if (failed) process.exit(1);
}

if (import.meta.main) {
  main();
}
